{
  "implementation": "def solve(case):
    nodes = case['nodes']
    required = set(case['required_symbols'])
    # Build maps
    node_by_id = {n['id']: n for n in nodes}
    children = {n['id']: [] for n in nodes}
    for n in nodes:
        p = n.get('parent')
        if p is not None:
            children.setdefault(p, []).append(n['id'])
    # Initial symbol counts
    symbol_count = {}
    for n in nodes:
        sym = n['symbol']
        symbol_count[sym] = symbol_count.get(sym, 0) + 1
    # All node ids initially retained
    retained = set(node_by_id.keys())
    removed = set()
    removal_order = []
    # Order: deeper first, then id string stable tie
    order = sorted(nodes, key=lambda n: (-n['depth'], n['id']))
    for n in order:
        nid = n['id']
        if nid in removed:
            continue
        if nid == 'root':
            continue
        if not n['removable']:
            continue
        if n['symbol'] in required:
            continue
        # Check retained children
        has_retained_child = False
        for cid in children.get(nid, []):
            if cid not in removed:
                has_retained_child = True
                break
        if has_retained_child:
            continue
        # Check required symbols after removal
        sym = n['symbol']
        current_count = symbol_count.get(sym, 0)
        ok = True
        for r in required:
            cnt = symbol_count.get(r, 0)
            if r == sym:
                cnt -= 1
            if cnt <= 0:
                ok = False
                break
        if not ok:
            continue
        # Remove
        removed.add(nid)
        retained.discard(nid)
        removal_order.append(nid)
        symbol_count[sym] = current_count - 1
    # Prepare output
    retained_sorted = sorted(retained)
    return {
        'removed_node_ids': removal_order,
        'retained_node_ids': retained_sorted
    }"
}
